Section FPX_1. Context {fx : PropExec.FPState}. Context {bmK : BMode}.   (* [comment removed for export] *)
Variable scfg : SpuriousCfg.


Section Usage.
  Context {RE : RunEnv}.
  Variable sp0 : word.
  Variables av envv : list (list byte).
  Variable uid : word.
  Variable hw : word.
  Variable rdraw : EntryDraw.
  Variable tid : word.
  Variable regs0 : bvmap 5 word.
  Variable mem0 : word -> option byte.
  Variable brk : word.
  Variable mbase : word.
  Variable fs0 : Fs.
  Variable stdin0 : InputStream.
  (* [comment removed for export] *)
  Variable lim : Z.
  Hypothesis Hva : valid_argv av.
  Hypothesis Hve : valid_envp envv.
  Hypothesis Hvsp : valid_sp sp0.
  Hypothesis Htid : (0 < bv_unsigned tid < 2 ^ 22)%Z.
  Hypothesis ME : main_entry sp0 av envv uid hw rdraw tid regs0 mem0.
  Hypothesis Hfits : entry_stack_fits sp0 av envv.   (* [comment removed for export] *)
  Hypothesis Hargc : length av <> 2%nat.

  Definition model0 : Model :=
    mkModelE fds_init (mkVmMapsFull (segments_reserved RSEGS) [] [] brk brk lim mbase sp0) stdin0 fs0 None (Some tid) None.

  Let SPlo : (0x7fff80000000 <= bv_unsigned sp0)%Z := proj1 Hvsp.
  Let SPhi : (bv_unsigned sp0 <= 0x800000000000)%Z := proj1 (proj2 Hvsp).

  Lemma model0_halted : m_halted model0 = None.
Proof.
ltac2:(KReplay.run1 (kr_t_Es0Usage ()) ["FPX_1"; "Usage"] "p;1p;2g0000j10Tg000Uj15Tg0013j12Tg001Vj11Tg0028j14Tg002Zj23Tg0034#0#0#0#0#0#0#5#2R0#1%40'3o"). Qed.
  Lemma model0_lazy : m_vm_lazy model0 = [].
Proof.
ltac2:(KReplay.run1 (kr_t_Es0Usage ()) ["FPX_1"; "Usage"] "p;1p;2g0000j10Tg000Uj16Tg0013j12Tg003Yj21Tg0049j15Tg004Yj14Tg002Zj23Tg0034#0#0#0#0#0#0#6#2R0/10R0#5%40'3o"). Qed.
  Lemma model0_fd2 : fd_lookup (m_fds model0) (Z_to_bv 64 2) = Some (FdChannel (Z_to_bv 64 2)).
Proof.
ltac2:(KReplay.run1 (kr_t_Es0Usage ()) ["FPX_1"; "Usage"] "p;1p;2p10059p4p70p1005gp4p710p8g001Vj17Tg0000j10Tg000Uj12Tg006Cj11Tg006aj26Tg007Gj15Tg008?j23Tg002Zj24Tg008aR0#7g0034#0R1#0#0#0#0#0#2%11'6#5,30'4o"). Qed.
  Lemma model0_fs : m_fs model0 = fs0.
Proof.
ltac2:(KReplay.run1 (kr_t_Es0Usage ()) ["FPX_1"; "Usage"] "p;2g002Zj20Tg0059p,3fs0'0o"). Qed.

